TWComponent.script:
var k = 0;
for (var i=0; i<tw.local.charges.listLength; i++) {
	if (tw.local.charges[i].rateType == "Fixed Rate") {
		tw.local.charges[i].defaultAmount = Number(tw.local.defaultAmountList[k].toFixed(2));
		tw.local.charges[i].changeAmount = Number(tw.local.defaultAmountList[k].toFixed(2));
		k+=1;
	}
}

tw.local.counter = 0;
tw.local.defaultPerList = [];
tw.local.defaultAmountList = [];

for (var i=0; i<tw.local.charges.listLength; i++) {
	if (tw.local.charges[i].rateType == "Fixed Rate") {
		tw.local.defaultPerList.insertIntoList(tw.local.defaultPerList.listLength, tw.local.charges[i].defaultPercentage+"");	
	}
}
tw.local.max = tw.local.defaultPerList.listLength;

