var k = 0;
for (var i=0; i<tw.local.charges.listLength; i++) {
	if (tw.local.charges[i].rateType == "Fixed Rate") {
		tw.local.charges[i].defaultAmount = Number(tw.local.defaultAmountList[k].toFixed(2));
